//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.gIndex;
scwin.gIsurCd;
scwin.gComAbbrv;
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.vScrenID = "ULDSTF37220.xml";
scwin.gParamObj = new Array(4);
scwin.LastJob = "";
scwin.gISUR_CD;
scwin.gCOM_NM;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    dts_EMP_NO.DataID = "/CodeAction.do?method=getEmpNoDepCode&inputMessageId=CODE_EMPDEP_IN&For=R&DEP_CD=" + scwin.gDepCd;
    dts_EMP_NO.Reset();
    dts_DEP_CD.DataID = "/CodeAction.do?method=getDepUpCode&inputMessageId=CODE_EMPDEP_IN&For=R&DEP_CD=" + scwin.gDepCd;
    dts_DEP_CD.Reset();

    //지정자문인 콤보박스 로딩
    dts_Design_Adviser.DataID = "/ListedCompany.do?method=listDesignAdviser" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Design_Adviser.Reset();
    var ToDay = new Date();
    var yyyy = parseInt(ToDay.getYear(), 10);
    $c.stf.setObjectValue(edt_BAS_YYYY, yyyy);
    $c.stf.setObjectValue(edt_BAS_YYYY2, yyyy);
    $c.stf.setObjectValue(edt_tab3_BAS_YYYY, yyyy);
};



// tab1 코넥스 상장법인 조회(책임자)
scwin.fn_Search = function() {
    var vISUR_CD = $c.stf.getObjectValue(txb_isur_cd);
    var vLIST_STAT_CD = $c.stf.getObjectValue(chb_LIST_STAT_CD);
    var vCOMPLT_YN = $c.stf.getObjectValue(cmb_COMPLT_YN);
    var vEDU_KIND_CD = $c.stf.getObjectValue(cmb_EDU_KIND_CD);
    var vBAS_YYYY = $c.stf.getObjectValue(edt_BAS_YYYY);
    var vDEP_CD = $c.stf.getObjectValue(cmb_DEP_CD);
    var vEMP_NO = $c.stf.getObjectValue(cmb_EMP_NO);
    var vCORP_CD = $c.stf.getObjectValue(cmb_CORP_CD);
    var url = "/ListedCompany.do?method=listCompanyPersonInChargeEducationCompletionKonex";
    url += "&ISUR_CD=" + vISUR_CD;
    url += "&LIST_STAT_CD=" + vLIST_STAT_CD;
    url += "&COMPLT_YN=" + vCOMPLT_YN;
    url += "&EDU_KIND_CD=" + vEDU_KIND_CD;
    url += "&BAS_YYYY=" + vBAS_YYYY;
    url += "&DEP_CD=" + vDEP_CD;
    url += "&EMP_NO=" + vEMP_NO;
    url += "&CORP_CD=" + vCORP_CD;
    url += "&DESIGN_ADVISE=";
    url += "&SCH_TP_CD=1"; // 같은 URL을 사용하기위해 책임자와 대리인의 조회 구분값을 던져준다. =>   1 : 책임자, 2 : 대리인
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Grid_Tab1.DataID = encodeURI(url);
    dts_Grid_Tab1.Reset();
    $c.cm.ShowWin(grd_Grid1);
};


// tab2 코넥스 지정자문인 조회(대리인)
scwin.fn_Search2 = function() {
    var vISUR_CD = $c.stf.getObjectValue(txb_isur_cd2);
    var vLIST_STAT_CD = $c.stf.getObjectValue(chb_LIST_STAT_CD2);
    var vCOMPLT_YN = $c.stf.getObjectValue(cmb_COMPLT_YN2);
    var vEDU_KIND_CD = $c.stf.getObjectValue(cmb_EDU_KIND_CD2);
    var vBAS_YYYY = $c.stf.getObjectValue(edt_BAS_YYYY2);
    var vDEP_CD = $c.stf.getObjectValue(cmb_DEP_CD2);
    var vEMP_NO = $c.stf.getObjectValue(cmb_EMP_NO2);
    var vCORP_CD = $c.stf.getObjectValue(cmb_CORP_CD2);
    var vDESIGN_ADVISE = $c.stf.getObjectValue(cmb_Design_advise);
    if (vCORP_CD == '') vCORP_CD = '1';
    var url = "/ListedCompany.do?method=listCompanyPersonInChargeEducationCompletionKonex";
    url += "&ISUR_CD=" + vISUR_CD;
    url += "&LIST_STAT_CD=" + vLIST_STAT_CD;
    url += "&COMPLT_YN=" + vCOMPLT_YN;
    url += "&EDU_KIND_CD=" + vEDU_KIND_CD;
    url += "&BAS_YYYY=" + vBAS_YYYY;
    url += "&DEP_CD=" + vDEP_CD;
    url += "&EMP_NO=" + vEMP_NO;
    url += "&CORP_CD=" + vCORP_CD;
    url += "&DESIGN_ADVISE=" + vDESIGN_ADVISE; // 지정자문인 코드
    url += "&SCH_TP_CD=2"; // 같은 URL을 사용하기위해 책임자와 대리인의 조회 구분값을 던져준다. =>   1 : 책임자, 2 : 대리인
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Grid_Tab2.DataID = encodeURI(url);
    dts_Grid_Tab2.Reset();
    $c.cm.ShowWin(grd_Grid2);
};
scwin.fn_tab3_Search = function() {
    //var vSEARCHTERM = getObjectValue(rdo_SearchTerm);	
    var vItab3_BAS_YYYY = $c.stf.getObjectValue(edt_tab3_BAS_YYYY);
    var vItab3_CHRG_TP_CD = $c.stf.getObjectValue(cmb_tab3_CHRG_TP_CD);
    var url = "/ListedCompany.do?method=listEducationScheduleKonex";
    url += "&tab3_BAS_YYYY=" + vItab3_BAS_YYYY;
    url += "&tab3_CHRG_TP_CD=" + vItab3_CHRG_TP_CD;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Grid_Tab3.DataID = encodeURI(url);
    dts_Grid_Tab3.Reset();
    $c.cm.ShowWin(grd_Grid3);
};
scwin.fn_read_tab2 = function(GridID, row, colid) {
    //작업해야함 
    var objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..		
    var CMD = "R";
    if (row < 1) return;

    //OPEN 
    if (colid == "COM_NM") {
        //상세화면 
        var vISUR_CD = objDataID.getCellData(row, "ISUR_CD");
        var vCOM_NM = objDataID.getCellData(row, "COM_NM");
        var vSTKCERT_LIST_DD = objDataID.getCellData(row, "STKCERT_LIST_DD");
        var url = "/issueinfo/ULDSTF30606.gfm?";
        url += "ISUR_CD=" + vISUR_CD;
        url += "&COM_NM=" + vCOM_NM;
        url += "&STKCERT_LIST_DD=" + vSTKCERT_LIST_DD;
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        if (scwin.fn_setParam(CMD, vISUR_CD, vCOM_NM, vSTKCERT_LIST_DD)) // formal arguments

        {
            //frame.CreateDialogFrame("child01", "/issueinfo/ULDSTF30606.gfm", "세부교육이수현황", 10, 10, 1000, 850, "window");
            $c.frame.path("../../").GWinOpen("child01", url, "세부교육이수현황", 10, 20, 990, 770, "");
        }
    }
};
scwin.fn_setParam = function() {
    // child에 param을 넘긴다.
    if (typeof(scwin.gParamObj) == "undefined") {
        $c.win.alert("전역변수 gParamObj를 선언하세요.");
        return false;
    }
    var argv = fn_setParam.arguments;
    var argc = fn_setParam.arguments.length;
    scwin.gParamObj = new Array(argc); // 초기화
    for (var i = 0; i < argc; i++) // actual arguments

    {
        eval("gParamObj.param" + i + " = argv[" + i + "]");
    }
    return true;
};
scwin.MxTab_1_OnSelChanged = function(nIndex) {
    if (nIndex == '1') {
        $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
        scwin.gIndex = nIndex;
        scwin.fn_Search();
    } else if (nIndex == '2') {
        $c.cm.fn_com_isur(txb_isur_cd2, txb_com_abbrv2);
        scwin.gIndex = nIndex;
        scwin.fn_Search2();
    } else {
        scwin.gIndex = nIndex;
        scwin.fn_tab3_Search();
    }
};
scwin.cmb_DEP_CD_OnSelChange = function() {
    dts_EMP_NO.sort("DEP_CD", 0);
    //dts_EMP_NO.sort(); // W-Craft 주석처리 
    dts_EMP_NO.UseFilter = true;
    dts_EMP_NO.Filter();
};
scwin.cmb_DEP_CD2_OnSelChange = function() {
    dts_EMP_NO.sort("DEP_CD", 0);
    //dts_EMP_NO.sort(); // W-Craft 주석처리 
    dts_EMP_NO.UseFilter = true;
    dts_EMP_NO.Filter();
};
scwin.dts_Grid_Tab1_OnLoadCompleted = function(rowcount) {
    var totalcnt = dts_Grid_Tab1.getCellData(rowcount, "RNUM");
    $c.stf.FillGridHeaderTotalCnt(totalcnt, panel_page);
    $c.cm.CloseWin(rowcount, grd_Grid1);
};
scwin.dts_Grid_Tab1_OnLoadError = function() {
    $c.stf.alert_error(dts_Grid_Tab2);
};
scwin.dts_Grid_Tab2_OnLoadCompleted = function(rowcount) {
    var totalcnt = dts_Grid_Tab2.getCellData(rowcount, "RNUM");
    $c.stf.FillGridHeaderTotalCnt(totalcnt, panel_page);
    $c.cm.CloseWin(rowcount, grd_Grid2);
};
scwin.dts_Grid_Tab2_OnLoadError = function() {
    $c.stf.alert_error(dts_Grid_Tab2);
};
scwin.dts_Grid_Tab3_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_Grid3);
};
scwin.dts_Grid_Tab3_OnLoadError = function() {
    $c.stf.alert_error(dts_Grid_Tab3);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.btn_tab3_Search_onclick = function() {
    scwin.fn_tab3_Search();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07, '');
    if (scwin.gIndex == '1') {
        $c.data.downloadGridViewExcel(grd_Grid1, "교육이수현황목록검색(상장법인)", "", "8");
    } else if (scwin.gIndex == '2') {
        $c.data.downloadGridViewExcel(grd_Grid2, "교육이수현황목록검색(지정자문인)", "", "8");
    } else if (scwin.gIndex == '3') {
        $c.data.downloadGridViewExcel(grd_Grid3, "교육일정목록검색", "", "8");
    }
};
scwin.grd_Grid2_OnDblClick = function(row, colid) {
    $c.win.alert("지정자문인의 경우 해당 기능을 제공하지 않습니다.");
};
scwin.grd_Grid1_OnDblClick = function(row, colid) {
    scwin.fn_read_tab2(grd_Grid1, row, colid);
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set2(scwin.gISUR_CD, scwin.gCOM_NM);
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set2(scwin.gISUR_CD, scwin.gCOM_NM);
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.dts_EMP_NO_OnFilter = function(row) {
    var vVal = ""; //getObjectValue(cmb_tab1_DEP_CD);
    if (vVal == "") {
        // 전체일 경우
        return true;
    } else {
        var vVal2 = dts_EMP_NO.getCellData(row, "dep_cd"); // 전체.
        if (vVal2 == "") return true; // 전체.
        return (vVal == vVal2) ? true : false;
    }
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.left = "100px";
    Grd_com_isur.style.top = "62px";
    Grd_com_isur.style.display = "none";
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.txb_isur_cd2_onfocus = function() {
    Grd_com_isur.style.left = "100px";
    Grd_com_isur.style.top = "62px";
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd2_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd2.getValue() == "") {
        txb_com_abbrv2.setValue("");
    }
};
scwin.txb_isur_cd2_onkeyup = function() {
    if (txb_isur_cd2.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
